INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「委細」の同義語として最も適切なものはどれか。', NULL, '["概要","詳細","大要","一部","概略"]', 1, '["「委細」は細かい事情や詳しい内容のこと。「詳細」も物事のこまかい内容を指し、同義語となる。「概要」「大要」「概略」はいずれも物事の大まかな内容を指し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「頑迷」の同義語として最も適切なものはどれか。', NULL, '["柔軟","聡明","強情","温厚","謙虚"]', 2, '["「頑迷」は頑固で道理をわきまえないこと。「強情」も自分の考えを押し通そうとする性質を指し、同義語となる。他の選択肢はいずれも柔らかい・穏やかな性質を表す語で意味が異なる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「寛容」の同義語として最も適切なものはどれか。', NULL, '["狭量","厳格","慎重","度量","頑固"]', 3, '["「寛容」は他人の言動を心広く受け入れること。「度量」も人を受け入れる心の広さを指す語であり、同義語となる。「狭量」は反対の意味、「厳格」「頑固」は無関係な性質を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「杞憂」の同義語として最も適切なものはどれか。', NULL, '["楽観","無用な心配","憂鬱","動揺","期待"]', 1, '["「杞憂」は中国の故事に由来し、実際には起こりえないことをあれこれ心配することを指す。「無用な心配」がその意味と一致する。他の選択肢は感情に関する語ではあるが、意味がずれている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「稀有」の同義語として最も適切なものはどれか。', NULL, '["普遍","平凡","豊富","卓越","希少"]', 4, '["「稀有」はめったにないこと、珍しいことを指す。「希少」も数が少なく珍しいことを指し、同義語となる。「普遍」「平凡」はありふれていることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「顕著」の同義語として最も適切なものはどれか。', NULL, '["曖昧","漠然","潜在","歴然","些細"]', 3, '["「顕著」ははっきりと目立つさま。「歴然」も、はっきりとしていて疑う余地がないさまを指し、同義語となる。「曖昧」「漠然」「潜在」はいずれもはっきりしないさまを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「厳格」の同義語として最も適切なものはどれか。', NULL, '["寛大","曖昧","厳正","柔和","温和"]', 2, '["「厳格」は規律などに厳しく、いい加減さを許さないこと。「厳正」も厳しく公正であることを指し、同義語となる。他の選択肢は寛容さや穏やかさを表す語であり、意味が異なる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「高尚」の同義語として最も適切なものはどれか。', NULL, '["卑俗","低俗","粗野","平凡","崇高"]', 4, '["「高尚」は程度が高く上品なこと、精神的に気高いことを指す。「崇高」も気高く尊いさまを指し、同義語となる。他の選択肢はいずれも下品・凡庸であることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「些細」の同義語として最も適切なものはどれか。', NULL, '["重大","甚大","深刻","些末","顕著"]', 3, '["「些細」は取るに足りないほど小さいこと。「些末」も同じく取るに足らないさまを指し、同義語となる。他の選択肢はいずれも重大であることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「秀逸」の同義語として最も適切なものはどれか。', NULL, '["平凡","拙劣","凡庸","粗雑","卓越"]', 4, '["「秀逸」は他より飛び抜けて優れていること。「卓越」も他よりはるかに優れていることを指し、同義語となる。他の選択肢はいずれも平凡・劣っていることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「潤沢」の同義語として最も適切なものはどれか。', NULL, '["欠乏","枯渇","貧弱","稀薄","豊富"]', 4, '["「潤沢」は物や資金などが豊かにあること。「豊富」も同義であり、同義語となる。他の選択肢はいずれも不足していることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「精緻」の同義語として最も適切なものはどれか。', NULL, '["粗雑","杜撰","大雑把","簡素","緻密"]', 4, '["「精緻」は細部まで極めて詳しく、精密に作られていること。「緻密」も同様に細かい点まで行き届いているさまを指し、同義語となる。他の選択肢はいずれも大まかで丁寧さに欠けることを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「遷延」の同義語として最も適切なものはどれか。', NULL, '["迅速","即座","敏速","遅延","早急"]', 3, '["「遷延」は物事が長引き、先延ばしになること。「遅延」も予定より遅れることを指し、同義語となる。他の選択肢はいずれも速やかであることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「造詣」の同義語として最も適切なものはどれか。', NULL, '["無知","浅学","無学","未熟","学識"]', 4, '["「造詣」はある分野についての深い知識や理解を指す。「学識」も学問上の深い知識を指し、同義語となる。他の選択肢はいずれも知識が乏しいことを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「抜群」の同義語として最も適切なものはどれか。', NULL, '["平凡","凡庸","並","劣等","出色"]', 4, '["「抜群」は多くのなかで飛び抜けて優れていること。「出色」も他より一段と優れていることを指し、同義語となる。他の選択肢はいずれも平凡・劣っていることを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「貪欲」の同義語として最も適切なものはどれか。', NULL, '["寡欲","淡泊","謙虚","節制","強欲"]', 4, '["「貪欲」は飽くことなく欲しがること。「強欲」も欲深いさまを指し、同義語となる。他の選択肢はいずれも欲が少ない、控えめであることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「泰然」の同義語として最も適切なものはどれか。', NULL, '["動揺","狼狽","焦燥","動転","沈着"]', 4, '["「泰然」は落ち着いていて物事に動じないさま。「沈着」も感情に流されず落ち着いていることを指し、同義語となる。他の選択肢はいずれも慌てふためくさまを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「難渋」の同義語として最も適切なものはどれか。', NULL, '["順調","円滑","快調","平坦","難航"]', 4, '["「難渋」は物事が思うように進まず、行き詰まること。「難航」も障害が多く進行が困難であることを指し、同義語となる。他の選択肢はいずれも物事が滞りなく進むことを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「敏捷」の同義語として最も適切なものはどれか。', NULL, '["鈍重","緩慢","遅鈍","悠長","俊敏"]', 4, '["「敏捷」は動作がすばやいこと。「俊敏」も頭の回転や動作がすばやいことを指し、同義語となる。他の選択肢はいずれも動作が鈍いことを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「平穏」の同義語として最も適切なものはどれか。', NULL, '["騒然","混乱","動乱","波乱","静穏"]', 4, '["「平穏」は変わったこともなく穏やかなこと。「静穏」も静かで穏やかなさまを指し、同義語となる。他の選択肢はいずれも騒がしく落ち着かない状態を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「卑近」の同義語として最も適切なものはどれか。', NULL, '["高遠","深遠","難解","抽象","身近"]', 4, '["「卑近」は身の回りにあってありふれていること。「身近」も日常に近いところにあることを指し、同義語となる。他の選択肢はいずれも高尚・難解であることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「頻繁」の同義語として最も適切なものはどれか。', NULL, '["稀","時折","滅多に","皆無","再三"]', 4, '["「頻繁」は物事が何度も繰り返し起こること。「再三」も何度も繰り返すさまを指し、同義語となる。他の選択肢はいずれも回数が少ないことを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「未曾有」の同義語として最も適切なものはどれか。', NULL, '["日常","恒常","平常","頻繁","空前"]', 4, '["「未曾有」はこれまで一度もなかったこと。「空前」も過去に例がないことを指し、同義語となる。他の選択肢はいずれもありふれている・日常的であることを表し、意味が逆になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「折衝」の同義語として最も適切なものはどれか。', NULL, '["服従","妥協","交渉","黙認","放棄"]', 2, '["「折衝」は利害の異なる相手と話し合いをすること。「交渉」も同じく相手と話し合って取り決めを行うことを指し、同義語となる。他の選択肢は交渉の一結果を表す語であり、意味の範囲が異なる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「邁進」の同義語として最も適切なものはどれか。', NULL, '["停滞","退却","躊躇","驀進","傍観"]', 3, '["「邁進」は目標に向かって力強く進むこと。「驀進」も勢いよくまっすぐに進むことを指し、同義語となる。他の選択肢はいずれも進むことをやめる、あるいは見ているだけの状態を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「質素」の反意語として最も適切なものはどれか。', NULL, '["倹約","簡素","素朴","華美","質朴"]', 3, '["「質素」は飾り気がなく地味なこと。「華美」は華やかで派手なことを指し、反意語となる。他の選択肢はいずれも「質素」と近い意味を持つ語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「寛大」の反意語として最も適切なものはどれか。', NULL, '["寛容","温情","厳格","大らか","狭量"]', 4, '["「寛大」は心が広く、他人の失敗などを厳しく責めないこと。「狭量」は心が狭く、他人を受け入れられないことを指し、反意語となる。「厳格」も近い候補だが、規律への厳しさを表す語であり、心の広さと正確に対をなすのは「狭量」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「富裕」の反意語として最も適切なものはどれか。', NULL, '["裕福","潤沢","豊潤","貧弱","貧困"]', 4, '["「富裕」は財産が豊かにあること。「貧困」は貧しく生活に困っていることを指し、反意語となる。「貧弱」は量や質に乏しいことを表す語であり、経済状態を直接表す「貧困」の方がより正確な反意語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「積極的」の反意語として最も適切なものはどれか。', NULL, '["能動的","主体的","意欲的","受動的","消極的"]', 4, '["「積極的」は自分から進んで物事に取り組む態度を指す。「消極的」は自ら進んでは行動しない、控えめな態度を指し、反意語となる。「受動的」も似た意味を持つが、「他から働きかけられる」という点に重点があり、「積極的」の対義語として最も一般的なのは「消極的」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「精密」の反意語として最も適切なものはどれか。', NULL, '["緻密","精巧","綿密","杜撰","粗雑"]', 4, '["「精密」は細部まで正確で狂いがないこと。「粗雑」は作りや扱いが大まかで雑なことを指し、反意語となる。「杜撰」も近い意味を持つが、いい加減さに焦点があり、「精密」に対する最も直接的な反意語は「粗雑」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「温厚」の反意語として最も適切なものはどれか。', NULL, '["温和","穏和","柔和","冷静","短気"]', 4, '["「温厚」は性格が穏やかで情け深いこと。「短気」は怒りっぽく、我慢が続かない性質を指し、反意語となる。他の選択肢はいずれも「温厚」と近い、穏やかな性質を表す語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「謙虚」の反意語として最も適切なものはどれか。', NULL, '["謙遜","卑屈","恭順","謙譲","尊大"]', 4, '["「謙虚」は自分を偉ぶらず、控えめな態度をとること。「尊大」は偉そうにふるまい、他人を見下すことを指し、反意語となる。他の選択肢はいずれも「謙虚」に近い、控えめな態度を表す語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「巧妙」の反意語として最も適切なものはどれか。', NULL, '["精巧","巧緻","老巧","稚拙","拙劣"]', 4, '["「巧妙」は技術や方法が非常に巧みなこと。「拙劣」は技術が未熟で下手なことを指し、反意語となる。「稚拙」も近い意味を持つが、幼稚さに重点がある語であり、「巧妙」に対する最も一般的な反意語は「拙劣」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「濃厚」の反意語として最も適切なものはどれか。', NULL, '["濃密","芳醇","深厚","希薄","淡白"]', 4, '["「濃厚」は味や色、可能性などが強く濃いこと。「淡白」は味や性格があっさりしていることを指し、反意語となる。「希薄」も近い意味を持つが、密度や量の少なさに重点がある語であり、味や性質については「淡白」がより適切な反意語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「厳格」の反意語として最も適切なものはどれか。', NULL, '["厳正","峻厳","苛烈","寛大","寛容"]', 4, '["「厳格」は規律などに対して厳しいこと。「寛容」は他人の言動を広い心で受け入れることを指し、反意語となる。「寛大」も近い候補だが、規律の厳しさに正確に対をなす語としては「寛容」がより一般的である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「冗長」の反意語として最も適切なものはどれか。', NULL, '["冗漫","長広舌","蛇足","簡素","簡潔"]', 4, '["「冗長」は文章や話が無駄に長いこと。「簡潔」は要点を押さえて簡単にまとめていることを指し、反意語となる。「簡素」も近い意味を持つが、装飾のなさに重点がある語であり、文章の長さについては「簡潔」がより適切な反意語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「慎重」の反意語として最も適切なものはどれか。', NULL, '["周到","用心深い","思慮深い","軽薄","軽率"]', 4, '["「慎重」は注意深く物事を進めること。「軽率」は物事をよく考えずに軽々しく行動することを指し、反意語となる。「軽薄」も近い意味を持つが、言動の浅はかさに重点がある語であり、「慎重」に対する最も一般的な反意語は「軽率」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「統一」の反意語として最も適切なものはどれか。', NULL, '["統合","一体化","集約","分散","分裂"]', 4, '["「統一」はばらばらのものを一つにまとめること。「分裂」は一つのものが分かれ、対立する状態になることを指し、反意語となる。「分散」も近い意味を持つが、単に散らばる意味合いが強く、対立を含意する「分裂」の方がより明確な反意語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「悲観」の反意語として最も適切なものはどれか。', NULL, '["悲哀","憂慮","絶望","失望","楽観"]', 4, '["「悲観」は物事を悪い方向に考え、望みを持てないこと。「楽観」は物事を良い方向に考え、心配しないことを指し、反意語となる。他の選択肢はいずれも「悲観」に近い、否定的な感情を表す語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「抽象」の反意語として最も適切なものはどれか。', NULL, '["概念","観念","理念","具象","具体"]', 4, '["「抽象」は物事から共通する性質を取り出し、一般化してとらえること。「具体」は個々の実際の姿や形を伴っていることを指し、反意語となる。「具象」も近い意味を持つが、芸術における表現形式を指す文脈で使われることが多く、一般的な反意語としては「具体」がより適切である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「拡大」の反意語として最も適切なものはどれか。', NULL, '["拡張","増大","膨張","減退","縮小"]', 4, '["「拡大」は物の規模や範囲を大きく広げること。「縮小」は規模や範囲を小さく縮めることを指し、反意語となる。「減退」も近い意味を持つが、勢いや力が衰える意味合いが強く、規模の変化を表す語としては「縮小」がより適切である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「過剰」の反意語として最も適切なものはどれか。', NULL, '["余剰","過多","冗費","欠乏","不足"]', 4, '["「過剰」は必要な量を超えて多すぎること。「不足」は必要な量に満たないことを指し、反意語となる。「欠乏」も近い意味を持つが、必要なものが著しく足りない状態を強調する語であり、「過剰」に対する最も一般的な反意語は「不足」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「迅速」の反意語として最も適切なものはどれか。', NULL, '["敏速","即座","機敏","遅滞","緩慢"]', 4, '["「迅速」は物事の進み方が非常に速いこと。「緩慢」は動きや進み方がゆっくりしていることを指し、反意語となる。「遅滞」も近い意味を持つが、本来進むべきものが滞る意味合いが強く、単純な速度の遅さを表す語としては「緩慢」がより適切である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「攻撃」の反意語として最も適切なものはどれか。', NULL, '["侵攻","進撃","猛攻","守備","防御"]', 4, '["「攻撃」は相手に対して積極的に仕掛けること。「防御」は相手の攻撃から自分を守ることを指し、反意語となる。「守備」も近い意味を持つが、主にスポーツなどの分野で使われる語であり、より一般的な反意語は「防御」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「保守」の反意語として最も適切なものはどれか。', NULL, '["保全","守旧","因習","改革","革新"]', 4, '["「保守」は従来の考え方や制度を守り、大きな変化を望まないこと。「革新」は古い制度や考え方を改め、新しくすることを指し、反意語となる。「改革」も近い意味を持つが、具体的な変更の行為そのものを指す語であり、「保守」に対応する思想的な反意語としては「革新」がより適切である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「濫費」の反意語として最も適切なものはどれか。', NULL, '["浪費","乱費","散財","倹約","節約"]', 4, '["「濫費」はお金や物を無駄に使いすぎること。「節約」は無駄を省いて大切に使うことを指し、反意語となる。「倹約」も近い意味を持つが、日々の生活を切り詰める意味合いが強く、「濫費」に対する最も一般的な反意語は「節約」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「栄転」の反意語として最も適切なものはどれか。', NULL, '["昇進","昇格","出世","降格","左遷"]', 4, '["「栄転」は今よりも高い地位や良い勤務地へ転任すること。「左遷」は今より低い地位や不遇な勤務地へ移されることを指し、反意語となる。「降格」も近い意味を持つが、地位の下降のみを指す語であり、転任という意味を含む「栄転」に対する反意語としては「左遷」がより適切である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「独創」の反意語として最も適切なものはどれか。', NULL, '["創造","創意","独自","剽窃","模倣"]', 4, '["「独創」は他に頼らず、自分自身で新しいものを生み出すこと。「模倣」は他のものをまねてつくることを指し、反意語となる。「剽窃」も近い意味を持つが、他人の成果を無断で自分のものとする不正行為を指す語であり、単に「まねる」ことを表す「模倣」の方がより一般的な反意語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「邪悪」の反意語として最も適切なものはどれか。', NULL, '["悪辣","凶悪","醜悪","善行","善良"]', 4, '["「邪悪」は心がねじ曲がっていて悪いこと。「善良」は心が素直で正しいことを指し、反意語となる。他の選択肢はいずれも「邪悪」に近い、悪い性質を表す語である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '同義語・対義語', NULL, '「繁栄」の反意語として最も適切なものはどれか。', NULL, '["隆盛","興隆","発展","衰微","衰退"]', 4, '["「繁栄」は勢いが盛んで栄えること。「衰退」は勢いが衰え、弱まっていくことを指し、反意語となる。「衰微」も近い意味を持つが、より深刻な衰えを表すやや文語的な語であり、「繁栄」に対する最も一般的な反意語は「衰退」である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: 同義語・対義語）');
